// Parity test: extract <script id="core"> from web/app.html, run it in node:vm, and replay every
// case in tests/vectors.json (generated by the Python library) against it.
// Tolerance: 1e-9 relative or absolute. Run: node web/parity.test.mjs
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import vm from "node:vm";

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, "app.html"), "utf8");
const m = html.match(/<script id="core">([\s\S]*?)<\/script>/);
if (!m) { console.error("core script block not found"); process.exit(1); }
const ctx = vm.createContext({ TextDecoder, TextEncoder, Uint8Array, DataView, Map, Set, URL, console });
vm.runInContext(m[1] + "\nthis.SB = SB;", ctx);
const SB = ctx.SB;
const V = JSON.parse(readFileSync(join(here, "..", "tests", "vectors.json"), "utf8"));
const REL = V.tolerance_rel, ABS = V.tolerance_abs;

// ---------------------------------------------------------------- tiny XML to DOM-like tree
// Stands in for the browser's DOMParser: elements with localName, children, getAttribute and
// textContent. Throws on anything not well formed, as DOMParser reports a parsererror.
function parseXmlDom(text) {
  const ENT = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" };
  const dec = (s) => s.replace(/&(#x[0-9a-fA-F]+|#\d+|\w+);?/g, (all, g) => {
    if (!all.endsWith(";")) throw new Error("bad entity");
    if (g[0] === "#") return String.fromCodePoint(g[1] === "x" ? parseInt(g.slice(2), 16) : parseInt(g.slice(1), 10));
    if (!(g in ENT)) throw new Error("undefined entity " + g);
    return ENT[g];
  });
  function El(name) {
    this.localName = name.includes(":") ? name.split(":")[1] : name;
    this.children = []; this.nodes = []; this.attrs = {};
  }
  El.prototype.getAttribute = function (n) { return n in this.attrs ? this.attrs[n] : null; };
  Object.defineProperty(El.prototype, "textContent", {
    get() { return this.nodes.map((x) => (typeof x === "string" ? x : x.textContent)).join(""); },
  });
  let i = 0, root = null;
  const stack = [];
  while (i < text.length) {
    if (text.startsWith("<?", i)) { const e = text.indexOf("?>", i); if (e < 0) throw new Error("pi"); i = e + 2; continue; }
    if (text.startsWith("<!--", i)) { const e = text.indexOf("-->", i); if (e < 0) throw new Error("comment"); i = e + 3; continue; }
    if (text.startsWith("<![CDATA[", i)) {
      const e = text.indexOf("]]>", i); if (e < 0 || !stack.length) throw new Error("cdata");
      stack[stack.length - 1].nodes.push(text.slice(i + 9, e)); i = e + 3; continue;
    }
    if (text.startsWith("<!", i)) throw new Error("declaration");
    if (text[i] === "<") {
      const e = text.indexOf(">", i);
      if (e < 0) throw new Error("tag");
      let tag = text.slice(i + 1, e);
      i = e + 1;
      if (tag[0] === "/") {
        const name = tag.slice(1).trim(), top = stack.pop();
        if (!top || top._name !== name) throw new Error("mismatched " + name);
        continue;
      }
      const self = tag.endsWith("/");
      if (self) tag = tag.slice(0, -1);
      const mm = /^([\w:.-]+)/.exec(tag);
      if (!mm) throw new Error("bad tag");
      const el = new El(mm[1]);
      el._name = mm[1];
      const re = /([\w:.-]+)\s*=\s*("([^"]*)"|'([^']*)')/g;
      let a;
      while ((a = re.exec(tag.slice(mm[1].length)))) el.attrs[a[1]] = dec(a[3] !== undefined ? a[3] : a[4]);
      if (stack.length) { const p = stack[stack.length - 1]; p.children.push(el); p.nodes.push(el); }
      else { if (root) throw new Error("two roots"); root = el; }
      if (!self) stack.push(el);
      continue;
    }
    const e = text.indexOf("<", i), chunk = text.slice(i, e < 0 ? text.length : e);
    if (stack.length) stack[stack.length - 1].nodes.push(dec(chunk));
    else if (chunk.trim()) throw new Error("text outside root");
    i = e < 0 ? text.length : e;
  }
  if (stack.length || !root) throw new Error("unclosed");
  return root;
}

// ---------------------------------------------------------------- adapters (same names as make_vectors.py)
const b64 = (s) => new Uint8Array(Buffer.from(s, "base64"));
async function inflate(bytes, method) {
  if (method === 0) return bytes;
  const ds = new DecompressionStream("deflate-raw");
  const out = await new Response(new Blob([bytes]).stream().pipeThrough(ds)).arrayBuffer();
  return new Uint8Array(out);
}
const ADAPT = {
  "@decodeFit": (s) => SB.decodeFit(b64(s)),
  "@parseXml": (kind, doc) => {
    const text = SB.xmlText(new TextEncoder().encode(doc));
    let root;
    try { root = parseXmlDom(text); } catch (e) { throw SB.err("xml", "The file is not well-formed XML."); }
    return kind === "gpx" ? SB.parseGpxDoc(root) : SB.parseTcxDoc(root);
  },
  "@scanHealth": (xml, n) => { const sc = SB.HealthScanner(); for (let i = 0; i < xml.length; i += n) sc.feed(xml.slice(i, i + n)); return sc.result(); },
  "@zipHealth": async (s) => {
    const raw = b64(s);
    const end = SB.zipEnd(raw.subarray(Math.max(0, raw.length - 65557 - 76)), Math.max(0, raw.length - 65557 - 76));
    const entries = SB.zipCentral(raw.subarray(end.offset, end.offset + end.size));
    const name = SB.findExportName(entries.map((e) => e.name));
    const ent = entries.find((e) => e.name === name);
    const off = SB.zipDataOffset(raw.subarray(ent.lho, ent.lho + 30), ent.lho);
    const data = await inflate(raw.subarray(off, off + ent.csize), ent.method);
    const sc = SB.HealthScanner();
    sc.feed(new TextDecoder().decode(data));
    return { entries, export: name, days: sc.result() };
  },
  "@readiness": (rows, day, s, loads) => { const o = SB.readiness(rows, day, SB.settingsWith(s), loads); o.text = SB.explain(o); return o; },
  "@mulberry": (seed, n) => { const r = SB.mulberry32(seed); return Array.from({ length: n }, () => r()); },
  "@example": (end, days) => {
    const [acts, daily] = SB.generateExample(end, days);
    return { daily, acts: acts.map((a) => {
      const r = SB.analyze(a, null);
      return { name: a.name, n: a.t.length, t_last: a.t[a.t.length - 1], lat_last: a.lat[a.lat.length - 1], hr_sum: a.hr.reduce((x, y) => x + y, 0),
        distance: r.distance, moving: r.moving, load: r.load, gain: r.elevation.gain, fastest_1k: r.fastest[1].time };
    }) };
  },
  "@signature": (a) => SB.signature(a, SB.cumdist(a)),
};

// ---------------------------------------------------------------- comparison
function norm(x) {
  if (x instanceof Map) { const o = {}; for (const [k, v] of x) o[String(k)] = norm(v); return o; }
  if (Array.isArray(x)) return x.map(norm);
  if (x && typeof x === "object") { const o = {}; for (const k of Object.keys(x)) o[k] = norm(x[k]); return o; }
  return x === undefined ? null : x;
}
let checks = 0, fails = 0;
function close(a, b, where) {
  checks++;
  if (b === null) { if (a !== null && !(typeof a === "number" && !Number.isFinite(a))) { fails++; console.error(`FAIL ${where}: ${JSON.stringify(a)?.slice(0, 80)} !== null`); } return; }
  if (typeof b === "number") {
    if (typeof a !== "number") { fails++; console.error(`FAIL ${where}: ${JSON.stringify(a)?.slice(0, 80)} is not ${b}`); return; }
    const d = Math.abs(a - b);
    if (!(d <= ABS || d <= REL * Math.max(Math.abs(a), Math.abs(b)))) { fails++; console.error(`FAIL ${where}: js=${a} py=${b}`); }
    return;
  }
  if (typeof b !== "object") { if (a !== b) { fails++; console.error(`FAIL ${where}: ${JSON.stringify(a)?.slice(0, 80)} !== ${JSON.stringify(b).slice(0, 80)}`); } return; }
  if (Array.isArray(b)) {
    if (!Array.isArray(a) || a.length !== b.length) { fails++; console.error(`FAIL ${where}: length ${a && a.length} vs ${b.length}`); return; }
    b.forEach((x, i) => close(a[i], x, `${where}[${i}]`));
    return;
  }
  if (a === null || typeof a !== "object") { fails++; console.error(`FAIL ${where}: not an object`); return; }
  for (const k of Object.keys(b)) close(a[k] === undefined ? null : a[k], b[k], `${where}.${k}`);
}

const counts = {};
for (const c of V.cases) {
  counts[c.fn] = (counts[c.fn] || 0) + 1;
  const where = `${c.fn}#${counts[c.fn]}`;
  const fn = ADAPT[c.fn] || SB[c.fn];
  if (!fn) { fails++; checks++; console.error(`FAIL ${where}: no JS function`); continue; }
  let out, code = null;
  try { out = await fn(...c.args); } catch (e) { code = e.code || ("exception: " + e.message); }
  if ("error" in c) { checks++; if (code !== c.error) { fails++; console.error(`FAIL ${where}: expected error ${c.error}, got ${code}`); } continue; }
  if (code !== null) { checks++; fails++; console.error(`FAIL ${where}: threw ${code}`); continue; }
  close(norm(out), c.out, where);
}

// ---------------------------------------------------------------- JS-only checks (no Python twin)
checks++;
if (SB.csvCell("=SUM(A1)") !== "'=SUM(A1)" || SB.csvCell("+1") !== "'+1" || SB.csvCell("-2") !== "'-2" || SB.csvCell("@x") !== "'@x" ||
    SB.csvCell('a,"b"') !== '"a,""b"""' || SB.csvCell(-2) !== "-2" || SB.csvCell(null) !== "") { fails++; console.error("FAIL csvCell"); }
checks++;
try { SB.checkXml('<!DOCTYPE x [<!ENTITY a "b">]><gpx/>'); fails++; console.error("FAIL doctype accepted"); } catch (e) { if (e.code !== "doctype") fails++; }

// Review fix: a FIT file of 3.1 million empty data messages is refused instead of filling memory.
{
  checks++;
  const N = 3100000, b = new Uint8Array(14 + 6 + N);
  b[0] = 14; new DataView(b.buffer).setUint32(4, 6 + N, true); b.set([0x2E, 0x46, 0x49, 0x54], 8); b.set([0x40, 0, 0, 20, 0, 0], 14);
  let code = null;
  try { SB.decodeFit(b); } catch (e) { code = e.code; }
  if (code !== "size") { fails++; console.error("FAIL fit message cap: " + code); }
}
// Review fix: the Health scanner stays linear on '>' inside an open quote.
{
  checks++;
  const sc = SB.HealthScanner(), t0 = Date.now();
  sc.feed('<Record type="HKQuantityTypeIdentifierHeartRate" value="');
  for (let i = 0; i < 20; i++) sc.feed(">".repeat(10000));
  if (Date.now() - t0 > 5000) { fails++; console.error("FAIL health scanner is slow on quoted '>'"); }
}

// network gate refusal paths
{
  const F = { maps: { hosts: ["tiles.openfreemap.org"] }, cloud: { hosts: (sw) => (sw.cloudHost ? [sw.cloudHost] : []) }, own: { urls: (sw) => (sw.aiBase ? [sw.aiBase] : []) } };
  const cases = [
    [{}, "maps", "https://tiles.openfreemap.org/x", false, "switch off"],
    [{ maps: true }, "maps", "https://tiles.openfreemap.org/styles/liberty", true, null],
    [{ maps: "yes" }, "maps", "https://tiles.openfreemap.org/x", false, "switch off"],
    [{ maps: true }, "maps", "http://tiles.openfreemap.org/x", false, "not https"],
    [{ maps: true }, "maps", "https://evil.example/x", false, "host not allowed"],
    [{ maps: true }, "maps", "https://tiles.openfreemap.org.evil.example/x", false, "host not allowed"],
    [{ maps: true }, "maps", "https://user:pw@tiles.openfreemap.org/x", false, "credentials in url"],
    [{ maps: true }, "maps", "https://tiles.openfreemap.org:8443/x", false, "port not allowed"],
    [{ maps: true }, "routing", "https://overpass-api.de/x", false, "unknown feature"],
    [{ maps: true }, "maps", "not a url", false, "bad url"],
    [{ cloud: true }, "cloud", "https://api.example.org/v1", false, "host not allowed"],
    [{ cloud: true, cloudHost: "api.example.org" }, "cloud", "https://api.example.org/v1", true, null],
    [{ maps: true }, "__proto__", "https://tiles.openfreemap.org/x", false, "unknown feature"],
    // exact-address feature (your own AI service): only the configured URL, https or http to this computer
    [{ own: true, aiBase: "https://ai.example.org/v1/chat/completions" }, "own", "https://ai.example.org/v1/chat/completions", true, null],
    [{ own: true, aiBase: "https://ai.example.org/v1/chat/completions" }, "own", "https://ai.example.org/v1/models", false, "address not allowed"],
    [{ own: true, aiBase: "https://ai.example.org/v1/chat/completions" }, "own", "https://evil.example/v1/chat/completions", false, "address not allowed"],
    [{ own: true, aiBase: "http://localhost:11434/v1/chat/completions" }, "own", "http://localhost:11434/v1/chat/completions", true, null],
    [{ own: true, aiBase: "http://localhost:11434/v1/chat/completions" }, "own", "http://localhost:8080/v1/chat/completions", false, "address not allowed"],
    [{ own: true, aiBase: "http://ai.example.org/v1/chat/completions" }, "own", "http://ai.example.org/v1/chat/completions", false, "not https"],
    [{ own: true, aiBase: "https://ai.example.org/v1/chat/completions" }, "own", "https://u:p@ai.example.org/v1/chat/completions", false, "credentials in url"],
    [{ aiBase: "https://ai.example.org/v1/chat/completions" }, "own", "https://ai.example.org/v1/chat/completions", false, "switch off"],
  ];
  for (const [sw, f, url, ok, reason] of cases) {
    checks++;
    const d = SB.netDecision(F, sw, f, url);
    if (d.ok !== ok || d.reason !== reason) { fails++; console.error(`FAIL netDecision ${f} ${url}: ${JSON.stringify(d)}`); }
  }
}

console.log(`${checks} checks over ${V.cases.length} cases, ${fails} failures`);
process.exit(fails ? 1 : 0);
